    """折叠当前审批人名单：approval_roster_updated 与
    target=approval-roster 的 policy_change_applied 按 seq 统一折叠，
    取最后一条快照；无事件为空名单。两类事件均已严格校验。"""
    current: list[str] = []
    # 先严格校验 legacy 名单事件（成员形状/去重/码点升序）。
    self._approval_roster_events_strict(wallet_id)
